import os

def delete_files(directory, num_files):
    for filename in os.listdir(directory):
        if len(os.listdir(directory)) <= num_files:
            break
        else:
            os.remove(os.path.join(directory, filename))

def main():
    directory = os.path.join(os.getcwd(), "files")
    num_files = 10000

    if not os.path.exists(directory):
        os.makedirs(directory)

    delete_files(directory, num_files)

    print(f"Files remaining: {len(os.listdir(directory))}")

if __name__ == "__main__":
    main()

